import java.util.*;

class Solution {
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public int minimumEffortPath(int[][] heights) {
        int rows = heights.length;
        int cols = heights[0].length;
        int[][] best = new int[rows][cols];
        for (int[] row : best) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(cell -> cell[0]));
        best[0][0] = 0;
        heap.offer(new int[] {0, 0, 0});

        while (!heap.isEmpty()) {
            int[] cell = heap.poll();
            int effort = cell[0];
            int r = cell[1];
            int c = cell[2];
            if (effort != best[r][c]) {
                continue;
            }
            if (r == rows - 1 && c == cols - 1) {
                return effort;
            }

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }
                int edgeEffort = Math.abs(heights[nr][nc] - heights[r][c]);
                int nextEffort = Math.max(effort, edgeEffort);
                if (nextEffort < best[nr][nc]) {
                    best[nr][nc] = nextEffort;
                    heap.offer(new int[] {nextEffort, nr, nc});
                }
            }
        }
        return 0;
    }
}

import java.util.*;

class Solution {
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public int minimumEffortPath(int[][] heights) {
        int low = 0;
        int high = 1_000_000;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (canReach(heights, mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private boolean canReach(int[][] heights, int limit) {
        int rows = heights.length;
        int cols = heights[0].length;
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[] {0, 0});
        visited[0][0] = true;

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0];
            int c = cell[1];
            if (r == rows - 1 && c == cols - 1) {
                return true;
            }
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || visited[nr][nc]) {
                    continue;
                }
                if (Math.abs(heights[nr][nc] - heights[r][c]) <= limit) {
                    visited[nr][nc] = true;
                    queue.offer(new int[] {nr, nc});
                }
            }
        }
        return false;
    }
}

import java.util.*;

class Solution {
    public int minimumEffortPath(int[][] heights) {
        int rows = heights.length;
        int cols = heights[0].length;
        if (rows == 1 && cols == 1) {
            return 0;
        }

        List<int[]> edges = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int id = r * cols + c;
                if (r + 1 < rows) {
                    edges.add(new int[] {Math.abs(heights[r][c] - heights[r + 1][c]), id, (r + 1) * cols + c});
                }
                if (c + 1 < cols) {
                    edges.add(new int[] {Math.abs(heights[r][c] - heights[r][c + 1]), id, r * cols + c + 1});
                }
            }
        }
        edges.sort(Comparator.comparingInt(edge -> edge[0]));

        UnionFind uf = new UnionFind(rows * cols);
        int target = rows * cols - 1;
        for (int[] edge : edges) {
            uf.union(edge[1], edge[2]);
            if (uf.connected(0, target)) {
                return edge[0];
            }
        }
        return 0;
    }

    static class UnionFind {
        private final int[] parent;
        private final int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            Arrays.fill(size, 1);
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) {
                return;
            }
            if (size[rootA] < size[rootB]) {
                int tmp = rootA;
                rootA = rootB;
                rootB = tmp;
            }
            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        boolean connected(int a, int b) {
            return find(a) == find(b);
        }
    }
}

import java.util.*;

class Solution {
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public int minimumEffortPath(int[][] heights) {
        int rows = heights.length;
        int cols = heights[0].length;
        int[][] best = new int[rows][cols];
        for (int[] row : best) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        Deque<int[]> queue = new ArrayDeque<>();
        boolean[][] inQueue = new boolean[rows][cols];
        best[0][0] = 0;
        queue.offer(new int[] {0, 0});
        inQueue[0][0] = true;

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0];
            int c = cell[1];
            inQueue[r][c] = false;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }
                int edgeEffort = Math.abs(heights[nr][nc] - heights[r][c]);
                int nextEffort = Math.max(best[r][c], edgeEffort);
                if (nextEffort < best[nr][nc]) {
                    best[nr][nc] = nextEffort;
                    if (!inQueue[nr][nc]) {
                        queue.offer(new int[] {nr, nc});
                        inQueue[nr][nc] = true;
                    }
                }
            }
        }
        return best[rows - 1][cols - 1];
    }
}
